export interface Membership {
  readonly id: string;
  readonly service: string;
  readonly active: boolean;
  readonly credits: number;
}

export interface MembershipContract {
  count(userId: string): Promise<number>;
  at(userId: string, index: number): Promise<Membership>;
  cancel(id: string): Promise<void>;
}

export class MembershipManager {
  private userId: string | null = null;
  private memberships: Membership[] = [];

  constructor(private readonly contract: MembershipContract) {}

  async refresh(userId: string): Promise<Membership[]> {
    const count = await this.contract.count(userId);
    if (!Number.isSafeInteger(count) || count < 0) throw new RangeError('invalid count');
    const next: Membership[] = [];
    for (let index = 1; index <= count; index++) {
      next.push({ ...(await this.contract.at(userId, index)) });
    }
    this.userId = userId;
    this.memberships = next;
    return this.snapshot();
  }

  visible(active: boolean): Membership[] {
    return this.memberships.filter(item => item.active === active).map(item => ({ ...item }));
  }

  async cancel(id: string): Promise<boolean> {
    if (this.userId === null) throw new Error('refresh required');
    const item = this.memberships.find(candidate => candidate.id === id);
    if (!item || !item.active) return false;
    await this.contract.cancel(id);
    await this.refresh(this.userId);
    return true;
  }

  private snapshot(): Membership[] {
    return this.memberships.map(item => ({ ...item }));
  }
}
