function ok(v: unknown, m = 'assertion failed'): asserts v { if (!v) throw new Error(m); }
function equal(a: unknown, b: unknown, m = 'values differ'): void { if (a !== b) throw new Error(`${m}: ${String(a)} !== ${String(b)}`); }
async function rejects(p: Promise<unknown>, kind?: Function): Promise<void> { try { await p; } catch (e) { if (kind) ok(e instanceof (kind as any)); return; } throw new Error('expected rejection'); }

(async () => {
  let rows: Membership[] = [{ id: 'a', service: 'A', active: true, credits: 2 }, { id: 'b', service: 'B', active: false, credits: 0 }];
  const calls: string[] = []; let badAt = -1; let invalidCount: number | null = null;
  const contract: MembershipContract = {
    count: async user => { calls.push(`count:${user}`); return invalidCount === null ? rows.length : invalidCount; },
    at: async (user, index) => { calls.push(`at:${user}:${index}`); if (index === badAt) throw new Error('at failed'); return rows[index]; },
    cancel: async id => { calls.push(`cancel:${id}`); rows = rows.map(x => x.id === id ? { ...x, active: false } : x); },
  };
  const manager = new MembershipManager(contract);
  await rejects(manager.cancel('a'), Error);
  const snapshot = await manager.refresh('u1');
  equal(calls.join(','), 'count:u1,at:u1:0,at:u1:1'); equal(snapshot.map(x => x.id).join(','), 'a,b');
  ok(snapshot[0] !== rows[0]); snapshot[0] = { ...snapshot[0], service: 'changed' }; equal(manager.visible(true)[0].service, 'A');
  const visible = manager.visible(false); visible[0] = { ...visible[0], service: 'x' }; equal(manager.visible(false)[0].service, 'B');
  calls.length = 0; equal(await manager.cancel('missing'), false); equal(calls.length, 0); equal(await manager.cancel('b'), false); equal(calls.length, 0);
  equal(await manager.cancel('a'), true); equal(calls.join(','), 'cancel:a,count:u1,at:u1:0,at:u1:1'); equal(manager.visible(true).length, 0);
  calls.length = 0; invalidCount = -1; await rejects(manager.refresh('bad'), RangeError); equal(calls.join(','), 'count:bad');
  for (const value of [1.5, Number.MAX_SAFE_INTEGER + 1]) { calls.length = 0; invalidCount = value; await rejects(manager.refresh('bad'), RangeError); equal(calls.length, 1); }
  invalidCount = null; rows = [{ id: 'x', service: 'X', active: true, credits: 1 }, { id: 'y', service: 'Y', active: true, credits: 1 }]; badAt = 1;
  await rejects(manager.refresh('u2')); equal(manager.visible(false).map(x => x.id).join(','), 'a,b');
})().catch(error => { throw error; });

